-- Catalogo de la IA de JanusApp (fuente de verdad: se carga con testing/ia/catalogo_cli.py crear)
PRAGMA foreign_keys=OFF;
BEGIN;
CREATE TABLE colores (token TEXT PRIMARY KEY, hex TEXT NOT NULL, tipo TEXT NOT NULL CHECK (tipo IN ('base','fijo')), palabras TEXT NOT NULL DEFAULT '', orden INTEGER NOT NULL DEFAULT 0);
CREATE TABLE colores_alias (palabra TEXT PRIMARY KEY, token TEXT NOT NULL);
CREATE TABLE formas (token TEXT PRIMARY KEY, descripcion TEXT NOT NULL DEFAULT '', palabras TEXT NOT NULL DEFAULT '', orden INTEGER NOT NULL DEFAULT 0);
CREATE TABLE meta (clave TEXT PRIMARY KEY, valor TEXT NOT NULL);
CREATE TABLE objetos (token TEXT PRIMARY KEY, descripcion TEXT NOT NULL, ficha TEXT NOT NULL DEFAULT '', orden INTEGER NOT NULL DEFAULT 0);
CREATE TABLE ordenes (token TEXT PRIMARY KEY, argumentos TEXT NOT NULL DEFAULT '', descripcion TEXT NOT NULL, ejemplo TEXT NOT NULL DEFAULT '', orden INTEGER NOT NULL DEFAULT 0);
CREATE TABLE plantillas (token TEXT PRIMARY KEY, descripcion TEXT NOT NULL, programa TEXT NOT NULL);
CREATE TABLE referencias (nombre TEXT PRIMARY KEY, alias TEXT NOT NULL DEFAULT '', descripcion TEXT NOT NULL DEFAULT '', alto_m REAL, ancho_m REAL, fondo_m REAL, objeto TEXT NOT NULL);
CREATE TABLE texturas (tipo TEXT PRIMARY KEY, descripcion TEXT NOT NULL, ejemplo TEXT NOT NULL DEFAULT '', orden INTEGER NOT NULL DEFAULT 0);
CREATE TABLE zonas (token TEXT PRIMARY KEY, textura TEXT NOT NULL, descripcion TEXT NOT NULL DEFAULT '', palabras TEXT NOT NULL DEFAULT '', orden INTEGER NOT NULL DEFAULT 0);
COMMIT;
